"use client"

import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { IconPlaceholder } from "@/components/blocks/_icon-placeholder"

/** Props a call site may pass through to an icon. */
type IconProps = { className?: string; size?: number | string }

const logos = [
  { name: "Slack", Icon: (p: IconProps) => <SlackMark {...p} /> },
  { name: "GitHub", Icon: (p: IconProps) => <GithubMark {...p} /> },
  { name: "Notion", Icon: (p: IconProps) => <NotionMark {...p} /> },
  { name: "Figma", Icon: (p: IconProps) => <FigmaMark {...p} /> },
  { name: "Vercel", Icon: (p: IconProps) => <VercelMark {...p} /> },
  {
    name: "Supabase",
    Icon: (p: IconProps) => (
      <IconPlaceholder
        lucide="Database"
        tabler="IconDatabase"
        hugeicons="DatabaseIcon"
        phosphor="Database"
        remixicon="RiSupabaseFill"
        {...p}
      />
    ),
  },
  { name: "Google", Icon: (p: IconProps) => <GoogleMark {...p} /> },
  { name: "Discord", Icon: (p: IconProps) => <DiscordMark {...p} /> },
  { name: "Spotify", Icon: (p: IconProps) => <SpotifyMark {...p} /> },
  { name: "OpenAI", Icon: (p: IconProps) => <OpenAIMark {...p} /> },
]

export default function LogoCloudBlock() {
  return (
    <section className="flex w-full items-center justify-center bg-muted/30 px-6 py-16 text-foreground">
      <div className="mx-auto w-full max-w-5xl text-center">
        <h2 className="font-heading text-2xl font-semibold tracking-tight sm:text-3xl">
          Powering teams everywhere
        </h2>
        <p className="mx-auto mt-3 max-w-md text-sm text-muted-foreground">
          Acme connects the tools your team already relies on, from day one.
        </p>

        <TooltipProvider delayDuration={150}>
          <ul className="mt-12 grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-border bg-border md:grid-cols-5">
            {logos.map(({ name, Icon }) => (
              <li key={name} className="bg-card">
                <Tooltip>
                  <TooltipTrigger
                   
                   asChild><div className="group flex h-24 w-full items-center justify-center"><Icon
                      aria-hidden="true"
                      className="size-8 text-muted-foreground/60 transition-colors duration-200 group-hover:text-foreground"
                    />
                    <span className="sr-only">{name}</span></div></TooltipTrigger>
                  <TooltipContent>{name}</TooltipContent>
                </Tooltip>
              </li>
            ))}
          </ul>
        </TooltipProvider>
      </div>
    </section>
  )
}

// Brand marks are inlined rather than imported from an icon library: the rest
// of this file uses IconPlaceholder, which resolves to whichever icon set the
// consumer already has, and one brand import would drag a whole extra package
// into their install for a handful of glyphs.
type MarkProps = React.ComponentProps<"svg"> & { size?: number | string }

